3	import java.util.List;
4	
5	/** DataIntegrityViolationException 원인 체인에서 위반된 제약(인덱스) 이름을 찾는다. */
6	public final class ConstraintNames {
7	
8	    public static final String UQ_COUPONS_CODE = "uq_coupons_code";
9	    public static final String UX_ORDERS_ACTIVE_USER_COUPON = "ux_orders_active_user_coupon";
10	
11	    private static final List<String> KNOWN = List.of(UQ_COUPONS_CODE, UX_ORDERS_ACTIVE_USER_COUPON);
12	
13	    private ConstraintNames() {
14	    }
15	
16	    public static String of(Throwable t) {
17	        for (Throwable c = t; c != null; c = c.getCause()) {
18	            if (c instanceof org.hibernate.exception.ConstraintViolationException cve
19	                    && cve.getConstraintName() != null) {
20	                String name = cve.getConstraintName();
21	                int dot = name.lastIndexOf('.');
22	                return dot >= 0 ? name.substring(dot + 1) : name;
23	            }
24	            if (c.getCause() == c) {
25	                break;
26	            }
27	        }
28	        for (Throwable c = t; c != null; c = c.getCause()) {
29	            String msg = c.getMessage();
30	            if (msg != null) {
31	                for (String k : KNOWN) {
32	                    if (msg.contains(k)) {
33	                        return k;
34	                    }
35	                }
36	            }
37	            if (c.getCause() == c) {
38	                break;
39	            }
40	        }
41	        return null;
42	    }
43	}
