3	import java.net.URI;
4	import java.util.List;
5	import java.util.Map;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.dao.DataIntegrityViolationException;
9	import org.springframework.http.HttpHeaders;
10	import org.springframework.http.HttpStatus;
11	import org.springframework.http.HttpStatusCode;
12	import org.springframework.http.MediaType;
13	import org.springframework.http.ProblemDetail;
14	import org.springframework.http.ResponseEntity;
15	import org.springframework.web.bind.MethodArgumentNotValidException;
16	import org.springframework.web.context.request.WebRequest;
17	import org.springframework.web.bind.annotation.ExceptionHandler;
18	import org.springframework.web.bind.annotation.RestControllerAdvice;
19	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
20	
21	@RestControllerAdvice
22	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
23	
24	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
25	    private static final String TYPE_PREFIX = "https://example.com/problems/";
26	
27	    @ExceptionHandler(BusinessException.class)
28	    public ResponseEntity<Object> handleBusiness(BusinessException ex) {
29	        return build(ex.getErrorCode(), ex.getMessage());
30	    }
31	
32	    @ExceptionHandler(jakarta.validation.ConstraintViolationException.class)
33	    public ResponseEntity<Object> handleConstraintViolation(jakarta.validation.ConstraintViolationException ex) {
34	        return build(ErrorCode.VALIDATION_ERROR, "Request validation failed");
35	    }
36	
37	    @ExceptionHandler(DataIntegrityViolationException.class)
38	    public ResponseEntity<Object> handleDataIntegrity(DataIntegrityViolationException ex) {
39	        String constraint = ConstraintNames.of(ex);
40	        if (ConstraintNames.UQ_COUPONS_CODE.equals(constraint)) {
41	            return build(ErrorCode.DUPLICATE_COUPON_CODE, "이미 존재하는 쿠폰 코드입니다.");
42	        }
43	        if (ConstraintNames.UX_ORDERS_ACTIVE_USER_COUPON.equals(constraint)) {
44	            return build(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
45	        }
46	        log.error("Unmapped data integrity violation", ex);
47	        return build(ErrorCode.INTERNAL_ERROR, "Internal server error");
48	    }
49	
50	    @ExceptionHandler(Exception.class)
51	    public ResponseEntity<Object> handleAny(Exception ex) {
52	        log.error("Unhandled exception", ex);
53	        return build(ErrorCode.INTERNAL_ERROR, "Internal server error");
54	    }
55	
56	    @Override
57	    protected ResponseEntity<Object> handleMethodArgumentNotValid(
58	            MethodArgumentNotValidException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
59	        ProblemDetail pd = ex.getBody();
60	        pd.setDetail("Request validation failed");
61	        List<Map<String, String>> errors = ex.getBindingResult().getFieldErrors().stream()
62	                .map(fe -> Map.of("field", fe.getField(), "message", String.valueOf(fe.getDefaultMessage())))
63	                .toList();
64	        pd.setProperty("errors", errors);
65	        return handleExceptionInternal(ex, pd, headers, status, request);
66	    }
67	
68	    @Override
69	    protected ResponseEntity<Object> handleExceptionInternal(
70	            Exception ex, Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
71	        ResponseEntity<Object> base = super.handleExceptionInternal(ex, body, headers, statusCode, request);
72	        if (base == null) {
73	            return null;
74	        }
75	        ProblemDetail pd = base.getBody() instanceof ProblemDetail p
76	                ? p
77	                : ProblemDetail.forStatusAndDetail(statusCode,
78	                        statusCode.value() >= 500 ? "Internal server error" : String.valueOf(ex.getMessage()));
79	        ErrorCode code = ErrorCode.fromStatus(statusCode.value());
80	        pd.setType(URI.create(TYPE_PREFIX + code.typeSlug()));
81	        pd.setTitle(reason(statusCode.value()));
82	        pd.setProperty("code", code.name());
83	        HttpHeaders h = new HttpHeaders();
84	        h.putAll(base.getHeaders());
85	        h.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
86	        return new ResponseEntity<>(pd, h, statusCode);
87	    }
88	
89	    private static ResponseEntity<Object> build(ErrorCode code, String detail) {
90	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.valueOf(code.status()), detail);
91	        pd.setType(URI.create(TYPE_PREFIX + code.typeSlug()));
92	        pd.setTitle(reason(code.status()));
93	        pd.setProperty("code", code.name());
94	        return ResponseEntity.status(code.status())
95	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
96	                .body(pd);
97	    }
98	
99	    private static String reason(int status) {
100	        HttpStatus hs = HttpStatus.resolve(status);
101	        return hs != null ? hs.getReasonPhrase() : "Error";
102	    }
103	}
