2	
3	public final class DiscountCalculator {
4	
5	    private DiscountCalculator() {
6	    }
7	
8	    /** R2.4: FIXED=value, RATE=floor(subtotal*value/100) -> maxDiscountAmount 상한 -> subtotal 상한 */
9	    public static long discount(Coupon coupon, long subtotal) {
10	        long d = coupon.getType() == CouponType.FIXED
11	                ? coupon.getValue()
12	                : Math.multiplyExact(subtotal, coupon.getValue()) / 100;
13	        if (coupon.getMaxDiscountAmount() != null) {
14	            d = Math.min(d, coupon.getMaxDiscountAmount());
15	        }
16	        return Math.min(d, subtotal);
17	    }
18	}
