27	        Coupon coupon = new Coupon(
28	                req.code(),
29	                CouponType.valueOf(req.type()),
30	                req.value(),
31	                req.minOrderAmount(),
32	                req.maxDiscountAmount(),
33	                req.totalQuantity(),
34	                Times.truncate(req.validFrom().toInstant()),
35	                Times.truncate(req.validUntil().toInstant()));
36	        try {
