1	package com.example.order.orders;
2	
3	import com.example.order.common.error.BusinessException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.idempotency.IdempotencyScope;
6	import com.example.order.idempotency.IdempotencyStore;
7	import com.example.order.idempotency.RequestHasher;
8	import com.example.order.idempotency.StoredResponse;
9	import com.example.order.orders.dto.CreateOrderRequest;
10	import com.example.order.orders.dto.PayRequest;
11	import org.slf4j.Logger;
12	import org.slf4j.LoggerFactory;
13	import org.springframework.stereotype.Component;
14	
15	/** 멱등 오케스트레이션. 트랜잭션이 없는 빈이다 (begin/release는 각각 별도 단기 트랜잭션). */
16	@Component
17	public class OrderFacade {
18	
19	    private static final Logger log = LoggerFactory.getLogger(OrderFacade.class);
20	
21	    private final IdempotencyStore idempotencyStore;
22	    private final RequestHasher hasher;
23	    private final OrderService orderService;
24	    private final PaymentService paymentService;
25	
26	    public OrderFacade(IdempotencyStore idempotencyStore, RequestHasher hasher, OrderService orderService,
27	                       PaymentService paymentService) {
28	        this.idempotencyStore = idempotencyStore;
29	        this.hasher = hasher;
30	        this.orderService = orderService;
31	        this.paymentService = paymentService;
32	    }
33	
34	    public StoredResponse create(String userId, String idempotencyKey, CreateOrderRequest request) {
35	        String hash = hasher.hash(IdempotencyScope.ORDER_CREATE, userId, "/api/orders", request);
36	        IdempotencyStore.BeginResult begin = idempotencyStore.begin(IdempotencyScope.ORDER_CREATE, idempotencyKey, hash);
37	        if (begin instanceof IdempotencyStore.Replay replay) {
38	            return replay.response();
39	        }
40	        long recordId = ((IdempotencyStore.Acquired) begin).recordId();
41	        try {
42	            return orderService.create(userId, request, recordId);
43	        } catch (RuntimeException e) {
44	            releaseQuietly(recordId);
45	            throw e;
46	        }
47	    }
48	
49	    public StoredResponse pay(long orderId, String userId, String idempotencyKey, PayRequest request) {
50	        String path = "/api/orders/" + orderId + "/pay";
51	        String hash = hasher.hash(IdempotencyScope.ORDER_PAY, userId, path, request);
52	        IdempotencyStore.BeginResult begin = idempotencyStore.begin(IdempotencyScope.ORDER_PAY, idempotencyKey, hash);
53	        if (begin instanceof IdempotencyStore.Replay replay) {
54	            return replay.response();
55	        }
56	        long recordId = ((IdempotencyStore.Acquired) begin).recordId();
57	        PaymentService.PayOutcome outcome;
58	        try {
59	            outcome = paymentService.pay(orderId, request.cardToken(), idempotencyKey, recordId);
60	        } catch (RuntimeException e) {
61	            releaseQuietly(recordId);
62	            throw e;
63	        }
64	        if (outcome instanceof PaymentService.Approved approved) {
65	            return approved.response();
66	        }
67	        // Declined: 서비스 트랜잭션(PAYMENT_FAILED)은 이미 커밋됨. 오류이므로 키를 해제하고 402.
68	        releaseQuietly(recordId);
69	        throw new BusinessException(ErrorCode.PAYMENT_DECLINED, "결제가 거절되었습니다.");
70	    }
71	
72	    private void releaseQuietly(long recordId) {
73	        try {
74	            idempotencyStore.release(recordId);
75	        } catch (RuntimeException ex) {
76	            log.error("멱등 레코드 해제 실패: id={}", recordId, ex);
77	        }
78	    }
79	}
