95	        for (OrderItemRequest item : items) {
96	            subtotal = Math.addExact(subtotal,
97	                    Math.multiplyExact(products.get(item.productId()).getPrice(), (long) item.quantity()));
98	        }
99	        long discount = coupon == null ? 0L : DiscountCalculator.discount(coupon, subtotal);
100	
101	        // ④ 409 재고: productId 오름차순으로 조건부 UPDATE
102	        List<OrderItemRequest> byProductId = items.stream()
103	                .sorted(Comparator.comparing(OrderItemRequest::productId)).toList();
104	        for (OrderItemRequest item : byProductId) {
105	            if (productRepository.tryReserve(item.productId(), item.quantity()) == 0) {
106	                throw new BusinessException(ErrorCode.INSUFFICIENT_STOCK,
107	                        "재고가 부족합니다: productId=" + item.productId());
108	            }
109	        }
110	
111	        // ⑤ 409 쿠폰
112	        if (coupon != null) {
113	            if (now.isBefore(coupon.getValidFrom()) || !now.isBefore(coupon.getValidUntil())) {
114	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "쿠폰 유효기간이 아닙니다.");
115	            }
116	            if (subtotal < coupon.getMinOrderAmount()) {
117	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "최소 주문 금액 미달입니다.");
118	            }
119	            couponRepository.lockById(coupon.getId());
120	            if (orderRepository.existsActiveCouponUsage(userId, coupon.getCode())) {
121	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
122	            }
123	            if (couponRepository.tryUse(coupon.getId()) == 0) {
124	                throw new BusinessException(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다.");
125	            }
126	        }
127	
128	        // ⑥ 저장
129	        Instant expiresAt = Times.truncate(now.plus(properties.paymentTtl()));
130	        Order order = new Order(userId, coupon == null ? null : coupon.getCode(), subtotal, discount, now, expiresAt);
131	        int lineNo = 0;
132	        for (OrderItemRequest item : items) {
133	            order.addItem(lineNo++, item.productId(), item.quantity(), products.get(item.productId()).getPrice());
134	        }
135	        try {
136	            orderRepository.saveAndFlush(order);
137	        } catch (DataIntegrityViolationException e) {
138	            if (ConstraintNames.UX_ORDERS_ACTIVE_USER_COUPON.equals(ConstraintNames.of(e))) {
139	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
140	            }
141	            throw e;
142	        }
143	
144	        // ⑦ 응답 직렬화 + 멱등 완료 기록 (같은 트랜잭션)
145	        String location = "/api/orders/" + order.getId();
146	        String json = toJson(OrderResponse.from(order));
147	        idempotencyStore.complete(idemRecordId, 201, json, location);
148	        return new StoredResponse(201, json, location);
149	    }
150	
151	    // ------------------------------------------------------------------ 조회
152	
153	    @Transactional(readOnly = true)
154	    public OrderResponse get(long id) {
155	        return orderRepository.findById(id)
156	                .map(OrderResponse::from)
157	                .orElseThrow(() -> notFound(id));
158	    }
159	
160	    @Transactional(readOnly = true)
161	    public OrderPageResponse list(String userId, OrderStatus status, int size, String cursor) {
162	        CursorCodec.Cursor c = cursor == null ? null : CursorCodec.decode(cursor);
163	        List<Order> rows = orderRepository.findPage(userId, status, c, size + 1);
164	        boolean hasNext = rows.size() > size;
165	        List<Order> page = hasNext ? rows.subList(0, size) : rows;
166	        String nextCursor = hasNext ? CursorCodec.encode(page.get(page.size() - 1)) : null;
167	        return new OrderPageResponse(page.stream().map(OrderResponse::from).toList(), nextCursor);
168	    }
169	
170	    // ------------------------------------------------------------------ 취소·환불 (§8)
171	
172	    @Transactional
173	    public OrderResponse cancel(long id) {
174	        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
175	        Instant now = Times.now(clock);
176	        switch (order.getStatus()) {
177	            case PENDING_PAYMENT -> {
178	                if (!now.isBefore(order.getExpiresAt())) {
179	                    throw invalidState(order); // 만료 전이는 스위퍼가 담당
180	                }
181	                order.cancel();
182	                inventory.releaseReservation(order);
183	                inventory.releaseCoupon(order);
184	            }
185	            case PAID -> {
186	                if (order.getPaymentId() != null) {
187	                    pgClient.refund(order.getPaymentId()); // 장애 시 예외 -> 롤백 -> 503
188	                }
189	                order.refund();
190	                inventory.restock(order);
191	                inventory.releaseCoupon(order);
192	            }
193	            default -> throw invalidState(order);
194	        }
195	        orderRepository.flush();
196	        return OrderResponse.from(order);
197	    }
198	
199	    // ------------------------------------------------------------------ 배송 (§8)
200	
201	    @Transactional
202	    public OrderResponse ship(long id) {
203	        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
204	        if (order.getStatus() != OrderStatus.PAID) {
205	            throw invalidState(order);
206	        }
207	        order.ship();
208	        return OrderResponse.from(order);
209	    }
210	
211	    @Transactional
212	    public OrderResponse deliver(long id) {
213	        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
214	        if (order.getStatus() != OrderStatus.SHIPPED) {
215	            throw invalidState(order);
216	        }
217	        order.deliver();
218	        return OrderResponse.from(order);
219	    }
220	
221	    // ------------------------------------------------------------------ 만료 (§9)
222	
223	    /** 스위퍼 전용. 주문 1건당 1 트랜잭션. 이미 처리됐거나 다른 트랜잭션이 잠근 주문은 건너뛴다. */
224	    @Transactional
225	    public boolean expire(long id, Instant now) {
226	        return orderRepository.lockExpiredForSweep(id, now).map(order -> {
227	            order.expire();
228	            inventory.releaseReservation(order);
229	            inventory.releaseCoupon(order);
230	            log.debug("expired order id={}", id);
231	            return true;
232	        }).orElse(false);
233	    }
234	
235	    // ------------------------------------------------------------------ 공통
236	
237	    private String toJson(OrderResponse response) {
238	        try {
239	            return objectMapper.writeValueAsString(response);
240	        } catch (JsonProcessingException e) {
241	            throw new IllegalStateException("응답 직렬화 실패", e);
242	        }
243	    }
244	
245	    private static BusinessException notFound(long id) {
246	        return new BusinessException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + id);
247	    }
248	
249	    private static BusinessException invalidState(Order order) {
250	        return new BusinessException(ErrorCode.INVALID_STATE,
251	                "처리할 수 없는 주문 상태입니다: id=" + order.getId() + ", status=" + order.getStatus());
252	    }
253	}
