1	package com.example.order.orders;
2	
3	import com.example.order.common.error.BusinessException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.common.time.Times;
6	import com.example.order.idempotency.IdempotencyStore;
7	import com.example.order.idempotency.StoredResponse;
8	import com.example.order.orders.dto.OrderResponse;
9	import com.example.order.payment.PaymentGatewayClient;
10	import com.example.order.payment.PgPaymentResult;
11	import com.example.order.payment.PgPaymentStatus;
12	import com.fasterxml.jackson.core.JsonProcessingException;
13	import com.fasterxml.jackson.databind.ObjectMapper;
14	import java.time.Clock;
15	import java.time.Instant;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	@Service
20	public class PaymentService {
21	
22	    /** 결제 결과. 거절은 예외가 아니라 값으로 반환해야 PAYMENT_FAILED 전이가 커밋된다. */
23	    public sealed interface PayOutcome permits Approved, Declined {
24	    }
25	
26	    public record Approved(StoredResponse response) implements PayOutcome {
27	    }
28	
29	    public record Declined() implements PayOutcome {
30	    }
31	
32	    private final OrderRepository orderRepository;
33	    private final OrderInventory inventory;
34	    private final IdempotencyStore idempotencyStore;
35	    private final PaymentGatewayClient pgClient;
36	    private final ObjectMapper objectMapper;
37	    private final Clock clock;
38	
39	    public PaymentService(OrderRepository orderRepository, OrderInventory inventory,
40	                          IdempotencyStore idempotencyStore, PaymentGatewayClient pgClient,
41	                          ObjectMapper objectMapper, Clock clock) {
42	        this.orderRepository = orderRepository;
43	        this.inventory = inventory;
44	        this.idempotencyStore = idempotencyStore;
45	        this.pgClient = pgClient;
46	        this.objectMapper = objectMapper;
47	        this.clock = clock;
48	    }
49	
50	    /** 주문 행 잠금(FOR UPDATE)을 PG 호출 동안 유지한다 (§7). */
51	    @Transactional
52	    public PayOutcome pay(long orderId, String cardToken, String idempotencyKey, long idemRecordId) {
53	        // ① 잠금 + 404
54	        Order order = orderRepository.findByIdForUpdate(orderId)
55	                .orElseThrow(() -> new BusinessException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + orderId));
56	
57	        // ② 상태·만료 검사 -> 409
58	        Instant now = Times.now(clock);
59	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || !now.isBefore(order.getExpiresAt())) {
60	            throw new BusinessException(ErrorCode.INVALID_STATE,
61	                    "결제할 수 없는 주문 상태입니다: id=" + orderId + ", status=" + order.getStatus());
62	        }
63	
64	        // ③ PG 호출 (total=0이면 생략)
65	        String paymentId = null;
66	        if (order.getTotalPrice() > 0) {
67	            PgPaymentResult result = pgClient.pay(orderId, order.getTotalPrice(), cardToken, idempotencyKey);
68	            paymentId = result.paymentId();
69	            if (result.status() == PgPaymentStatus.DECLINED) {
70	                // ④ 거절: PAYMENT_FAILED + 예약·쿠폰 복원, 커밋
71	                order.markPaymentFailed(paymentId);
72	                inventory.releaseReservation(order);
73	                inventory.releaseCoupon(order);
74	                orderRepository.flush();
75	                return new Declined();
76	            }
77	        }
78	
79	        // ⑤ 승인 (또는 total=0)
80	        order.markPaid(paymentId, Times.now(clock));
81	        inventory.commitReservation(order);
82	        orderRepository.flush();
83	        String json = toJson(OrderResponse.from(order));
84	        idempotencyStore.complete(idemRecordId, 200, json, null);
85	        return new Approved(new StoredResponse(200, json, null));
86	    }
87	
88	    private String toJson(OrderResponse response) {
89	        try {
90	            return objectMapper.writeValueAsString(response);
91	        } catch (JsonProcessingException e) {
92	            throw new IllegalStateException("응답 직렬화 실패", e);
93	        }
94	    }
95	}
