3	import com.example.order.coupon.CouponRepository;
4	import com.example.order.product.ProductRepository;
5	import java.util.Comparator;
6	import java.util.List;
7	import org.springframework.stereotype.Component;
8	
9	/**
10	 * 주문 상태 전이에 따른 재고·쿠폰 카운터 변경(전부 네이티브 UPDATE). 호출자의 트랜잭션 안에서 실행된다.
11	 * 상품은 항상 productId 오름차순으로 갱신해 잠금 순서를 고정한다.
12	 */
13	@Component
14	class OrderInventory {
15	
16	    private final ProductRepository productRepository;
17	    private final CouponRepository couponRepository;
18	
19	    OrderInventory(ProductRepository productRepository, CouponRepository couponRepository) {
20	        this.productRepository = productRepository;
21	        this.couponRepository = couponRepository;
22	    }
23	
24	    /** 거절·만료·취소: reserved -= q */
25	    void releaseReservation(Order order) {
26	        for (OrderItem i : sorted(order)) {
27	            productRepository.releaseReservation(i.getProductId(), i.getQuantity());
28	        }
29	    }
30	
31	    /** 결제 승인: stock -= q, reserved -= q */
32	    void commitReservation(Order order) {
33	        for (OrderItem i : sorted(order)) {
34	            productRepository.commitReservation(i.getProductId(), i.getQuantity());
35	        }
36	    }
37	
38	    /** 환불: stock += q */
39	    void restock(Order order) {
40	        for (OrderItem i : sorted(order)) {
41	            productRepository.restock(i.getProductId(), i.getQuantity());
42	        }
43	    }
44	
45	    /** 쿠폰 사용 복원 (쿠폰이 있을 때만) */
46	    void releaseCoupon(Order order) {
47	        if (order.getCouponCode() != null) {
48	            couponRepository.releaseUse(order.getCouponCode());
49	        }
50	    }
51	
52	    private static List<OrderItem> sorted(Order order) {
53	        return order.getItems().stream().sorted(Comparator.comparing(OrderItem::getProductId)).toList();
54	    }
55	}
