6	
7	public class OrderQueryRepositoryImpl implements OrderQueryRepository {
8	
9	    private final EntityManager em;
10	
11	    public OrderQueryRepositoryImpl(EntityManager em) {
12	        this.em = em;
13	    }
14	
15	    @Override
16	    public List<Order> findPage(String userId, OrderStatus status, CursorCodec.Cursor cursor, int limit) {
17	        StringBuilder jpql = new StringBuilder("select o from Order o where 1=1");
18	        if (userId != null) {
19	            jpql.append(" and o.userId = :userId");
20	        }
21	        if (status != null) {
22	            jpql.append(" and o.status = :status");
23	        }
24	        if (cursor != null) {
25	            jpql.append(" and (o.createdAt < :cAt or (o.createdAt = :cAt and o.id < :cId))");
26	        }
