3	import com.example.order.common.error.BusinessException;
4	import com.example.order.common.error.ErrorCode;
5	import java.nio.charset.StandardCharsets;
6	import java.time.Instant;
7	import java.util.Base64;
8	
9	/** base64url(무패딩)( "{epochMicros}:{id}" ) */
10	public final class CursorCodec {
11	
12	    // PostgreSQL timestamptz 범위 안전 마진: 0001-01-01 ~ 9999-12-31
13	    private static final long MIN_MICROS = -62_135_596_800L * 1_000_000L;
14	    private static final long MAX_MICROS = 253_402_300_799L * 1_000_000L;
15	
16	    public record Cursor(Instant createdAt, long id) {
17	    }
18	
19	    private CursorCodec() {
20	    }
21	
22	    public static String encode(Order order) {
23	        Instant t = order.getCreatedAt();
24	        long micros = t.getEpochSecond() * 1_000_000L + t.getNano() / 1_000;
25	        String raw = micros + ":" + order.getId();
26	        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
27	    }
28	
29	    public static Cursor decode(String cursor) {
30	        try {
31	            String raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
32	            String[] parts = raw.split(":", -1);
33	            if (parts.length != 2) {
34	                throw invalid();
35	            }
36	            long micros = Long.parseLong(parts[0]);
37	            long id = Long.parseLong(parts[1]);
38	            if (id <= 0 || micros < MIN_MICROS || micros > MAX_MICROS) {
39	                throw invalid();
40	            }
41	            return new Cursor(
42	                    Instant.ofEpochSecond(Math.floorDiv(micros, 1_000_000L), Math.floorMod(micros, 1_000_000L) * 1_000L),
43	                    id);
44	        } catch (IllegalArgumentException e) { // base64 오류, NumberFormatException 포함
45	            throw invalid();
46	        }
47	    }
48	
49	    private static BusinessException invalid() {
50	        return new BusinessException(ErrorCode.VALIDATION_ERROR, "cursor를 해석할 수 없습니다.");
51	    }
52	}
