1	package com.example.order.idempotency;
2	
3	import com.example.order.common.error.BusinessException;
4	import com.example.order.common.error.ErrorCode;
5	import java.util.List;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.stereotype.Component;
8	import org.springframework.transaction.PlatformTransactionManager;
9	import org.springframework.transaction.TransactionDefinition;
10	import org.springframework.transaction.support.TransactionTemplate;
11	
12	@Component
13	public class IdempotencyStore {
14	
15	    public sealed interface BeginResult permits Acquired, Replay {
16	    }
17	
18	    /** 키 선점 성공: 이 요청이 owner */
19	    public record Acquired(long recordId) implements BeginResult {
20	    }
21	
22	    /** 이미 COMPLETED: 저장된 응답을 재생 */
23	    public record Replay(StoredResponse response) implements BeginResult {
24	    }
25	
26	    private record Row(long id, String requestHash, String status, Integer responseStatus, String responseBody,
27	                       String responseLocation) {
28	    }
29	
30	    private static final int MAX_ATTEMPTS = 3;
31	
32	    private static final String INSERT_SQL = """
33	            INSERT INTO idempotency_keys (scope, idem_key, request_hash, status)
34	            VALUES (?, ?, ?, 'IN_PROGRESS')
35	            ON CONFLICT (scope, idem_key) DO NOTHING
36	            RETURNING id""";
37	
38	    private static final String SELECT_SQL = """
39	            SELECT id, request_hash, status, response_status, response_body, response_location
40	              FROM idempotency_keys WHERE scope = ? AND idem_key = ?""";
41	
42	    private static final String COMPLETE_SQL = """
43	            UPDATE idempotency_keys
44	               SET status = 'COMPLETED', response_status = ?, response_body = ?, response_location = ?,
45	                   completed_at = now()
46	             WHERE id = ? AND status = 'IN_PROGRESS'""";
47	
48	    private static final String RELEASE_SQL =
49	            "DELETE FROM idempotency_keys WHERE id = ? AND status = 'IN_PROGRESS'";
50	
51	    private final JdbcTemplate jdbc;
52	    private final TransactionTemplate requiresNew;
53	
54	    public IdempotencyStore(JdbcTemplate jdbc, PlatformTransactionManager transactionManager) {
55	        this.jdbc = jdbc;
56	        this.requiresNew = new TransactionTemplate(transactionManager);
57	        this.requiresNew.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
58	    }
59	
60	    /** 비즈니스 트랜잭션 밖에서 호출한다. 선점 INSERT는 별도 트랜잭션으로 즉시 커밋된다. */
61	    public BeginResult begin(IdempotencyScope scope, String key, String requestHash) {
62	        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
63	            List<Long> ids = requiresNew.execute(status ->
64	                    jdbc.query(INSERT_SQL, (rs, i) -> rs.getLong(1), scope.name(), key, requestHash));
65	            if (ids != null && !ids.isEmpty()) {
66	                return new Acquired(ids.get(0));
67	            }
68	            List<Row> rows = jdbc.query(SELECT_SQL, (rs, i) -> new Row(
69	                    rs.getLong("id"),
70	                    rs.getString("request_hash"),
71	                    rs.getString("status"),
72	                    (Integer) rs.getObject("response_status"),
73	                    rs.getString("response_body"),
74	                    rs.getString("response_location")), scope.name(), key);
75	            if (rows.isEmpty()) {
76	                continue; // owner가 그 사이 실패해 삭제 -> 다시 선점 시도
77	            }
78	            Row row = rows.get(0);
79	            if (!row.requestHash().equals(requestHash)) {
80	                throw new BusinessException(ErrorCode.IDEMPOTENCY_KEY_MISMATCH,
81	                        "같은 Idempotency-Key로 다른 요청이 전달되었습니다.");
82	            }
83	            if ("COMPLETED".equals(row.status())) {
84	                return new Replay(new StoredResponse(row.responseStatus(), row.responseBody(), row.responseLocation()));
85	            }
86	            throw new BusinessException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 키의 요청이 처리 중입니다.");
87	        }
88	        throw new BusinessException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 키의 요청이 처리 중입니다.");
89	    }
90	
91	    /** 비즈니스 트랜잭션 안에서 호출한다(같은 커넥션에 참여). */
92	    public void complete(long recordId, int status, String bodyJson, String location) {
93	        int updated = jdbc.update(COMPLETE_SQL, status, bodyJson, location, recordId);
94	        if (updated != 1) {
95	            throw new IllegalStateException("멱등 레코드 완료 처리 실패: id=" + recordId);
96	        }
97	    }
98	
99	    /** 오류로 끝난 요청의 키를 삭제한다. 비즈니스 트랜잭션이 끝난 뒤 별도 트랜잭션으로 실행한다. */
100	    public void release(long recordId) {
101	        requiresNew.executeWithoutResult(status -> jdbc.update(RELEASE_SQL, recordId));
102	    }
103	}
