3	import com.fasterxml.jackson.databind.MapperFeature;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import com.fasterxml.jackson.core.JsonProcessingException;
6	import java.nio.charset.StandardCharsets;
7	import java.security.MessageDigest;
8	import java.security.NoSuchAlgorithmException;
9	import java.util.HexFormat;
10	import org.springframework.stereotype.Component;
11	
12	@Component
13	public class RequestHasher {
14	
15	    private final ObjectMapper canonicalMapper;
16	
17	    public RequestHasher(ObjectMapper objectMapper) {
18	        this.canonicalMapper = objectMapper.copy().configure(MapperFeature.SORT_PROPERTIES_ALPHABETICALLY, true);
19	    }
20	
21	    /** canonical = scope \n userId(없으면 "") \n "POST " path \n canonicalJson(dto) -> SHA-256 hex */
22	    public String hash(IdempotencyScope scope, String userId, String path, Object requestDto) {
23	        String json;
24	        try {
25	            json = canonicalMapper.writeValueAsString(requestDto);
26	        } catch (JsonProcessingException e) {
27	            throw new IllegalStateException("요청 직렬화 실패", e);
28	        }
29	        String canonical = scope.name() + "\n"
30	                + (userId == null ? "" : userId) + "\n"
31	                + "POST " + path + "\n"
32	                + json;
33	        try {
34	            MessageDigest md = MessageDigest.getInstance("SHA-256");
35	            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
36	        } catch (NoSuchAlgorithmException e) {
37	            throw new IllegalStateException(e);
38	        }
39	    }
40	}
