40	            } catch (IllegalArgumentException e) {
41	                throw new PaymentGatewayUnavailableException("PG 응답 status가 계약과 다릅니다.", e);
42	            }
43	            return new PgPaymentResult(paymentId, status);
44	        } catch (PaymentGatewayUnavailableException e) {
45	            throw e;
