3	import com.example.order.common.time.Times;
4	import com.fasterxml.jackson.annotation.JsonIgnore;
5	import jakarta.validation.constraints.AssertTrue;
6	import jakarta.validation.constraints.Min;
7	import jakarta.validation.constraints.NotNull;
8	import jakarta.validation.constraints.Pattern;
9	import jakarta.validation.constraints.PositiveOrZero;
10	import java.time.OffsetDateTime;
11	
12	public record CreateCouponRequest(
13	        @NotNull @Pattern(regexp = "^[A-Z0-9]{4,20}$") String code,
14	        @NotNull @Pattern(regexp = "^(FIXED|RATE)$") String type,
15	        @NotNull @Min(1) Long value,
16	        @PositiveOrZero Long minOrderAmount,
17	        @Min(1) Long maxDiscountAmount,
18	        @NotNull @Min(1) Long totalQuantity,
19	        @NotNull OffsetDateTime validFrom,
20	        @NotNull OffsetDateTime validUntil) {
21	
22	    @JsonIgnore
23	    @AssertTrue(message = "RATE 쿠폰의 value는 1~100이어야 합니다")
24	    public boolean isRateValueInRange() {
25	        if (!"RATE".equals(type) || value == null) {
26	            return true;
27	        }
28	        return value <= 100;
29	    }
30	
31	    @JsonIgnore
32	    @AssertTrue(message = "validFrom은 validUntil보다 이전이어야 합니다")
33	    public boolean isValidPeriod() {
34	        if (validFrom == null || validUntil == null) {
35	            return true;
36	        }
37	        // 저장될 값과 같은 정밀도(마이크로초 절사)로 비교해야 ck_coupons_validity 위반이 500으로 새지 않는다
38	        return Times.truncate(validFrom.toInstant()).isBefore(Times.truncate(validUntil.toInstant()));
39	    }
40	}
