66	    // ------------------------------------------------------------------ 생성 (§6)
67	
68	    @Transactional
69	    public StoredResponse create(String userId, CreateOrderRequest req, long idemRecordId) {
70	        Instant now = Times.now(clock);
71	        List<OrderItemRequest> items = req.items();
72	
73	        // ① 404 상품 (요청 순서대로 첫 번째 누락)
74	        Set<Long> ids = new HashSet<>();
75	        items.forEach(i -> ids.add(i.productId()));
76	        Map<Long, Product> products = productRepository.findAllById(ids).stream()
77	                .collect(Collectors.toMap(Product::getId, Function.identity()));
78	        for (OrderItemRequest item : items) {
79	            if (!products.containsKey(item.productId())) {
80	                throw new BusinessException(ErrorCode.PRODUCT_NOT_FOUND,
81	                        "상품을 찾을 수 없습니다: id=" + item.productId());
82	            }
83	        }
84	
85	        // ② 404 쿠폰
86	        Coupon coupon = null;
87	        if (req.couponCode() != null) {
88	            if (req.couponCode().indexOf('\u0000') >= 0) { // PostgreSQL이 NUL 문자열을 거부하므로 조회 없이 미존재 처리
89	                throw new BusinessException(ErrorCode.COUPON_NOT_FOUND, "쿠폰을 찾을 수 없습니다.");
90	            }
91	            coupon = couponRepository.findByCode(req.couponCode())
92	                    .orElseThrow(() -> new BusinessException(ErrorCode.COUPON_NOT_FOUND,
93	                            "쿠폰을 찾을 수 없습니다: code=" + req.couponCode()));
94	        }
95	
96	        // ③ 금액 계산
97	        long subtotal = 0;
98	        for (OrderItemRequest item : items) {
99	            subtotal = Math.addExact(subtotal,
100	                    Math.multiplyExact(products.get(item.productId()).getPrice(), (long) item.quantity()));
101	        }
102	        long discount = coupon == null ? 0L : DiscountCalculator.discount(coupon, subtotal);
103	
104	        // ④ 409 재고: productId 오름차순으로 조건부 UPDATE
105	        List<OrderItemRequest> byProductId = items.stream()
106	                .sorted(Comparator.comparing(OrderItemRequest::productId)).toList();
107	        for (OrderItemRequest item : byProductId) {
108	            if (productRepository.tryReserve(item.productId(), item.quantity()) == 0) {
109	                throw new BusinessException(ErrorCode.INSUFFICIENT_STOCK,
110	                        "재고가 부족합니다: productId=" + item.productId());
111	            }
112	        }
113	
114	        // ⑤ 409 쿠폰
115	        if (coupon != null) {
116	            if (now.isBefore(coupon.getValidFrom()) || !now.isBefore(coupon.getValidUntil())) {
117	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "쿠폰 유효기간이 아닙니다.");
118	            }
119	            if (subtotal < coupon.getMinOrderAmount()) {
120	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "최소 주문 금액 미달입니다.");
121	            }
122	            couponRepository.lockById(coupon.getId());
123	            if (orderRepository.existsActiveCouponUsage(userId, coupon.getCode())) {
124	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
125	            }
126	            if (couponRepository.tryUse(coupon.getId()) == 0) {
127	                throw new BusinessException(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다.");
128	            }
129	        }
130	
131	        // ⑥ 저장
132	        Instant expiresAt = Times.truncate(now.plus(properties.paymentTtl()));
133	        Order order = new Order(userId, coupon == null ? null : coupon.getCode(), subtotal, discount, now, expiresAt);
134	        int lineNo = 0;
135	        for (OrderItemRequest item : items) {
136	            order.addItem(lineNo++, item.productId(), item.quantity(), products.get(item.productId()).getPrice());
137	        }
138	        try {
139	            orderRepository.saveAndFlush(order);
140	        } catch (DataIntegrityViolationException e) {
141	            if (ConstraintNames.UX_ORDERS_ACTIVE_USER_COUPON.equals(ConstraintNames.of(e))) {
142	                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
143	            }
144	            throw e;
145	        }
146	
147	        // ⑦ 응답 직렬화 + 멱등 완료 기록 (같은 트랜잭션)
148	        String location = "/api/orders/" + order.getId();
149	        String json = toJson(OrderResponse.from(order));
150	        idempotencyStore.complete(idemRecordId, 201, json, location);
151	        return new StoredResponse(201, json, location);
152	    }
