122	
123	    public void delayRefunds(long millis) {
124	        refundMode = Mode.DELAY;
125	        delayMillis = millis;
126	    }
127	
128	    // ---- 관측 ----
129	
130	    public int paymentCalls() {
131	        return paymentCalls.get();
132	    }
133	
134	    public int refundCalls() {
135	        return refundCalls.get();
136	    }
137	
138	    public List<ReceivedPayment> receivedPayments() {
139	        return List.copyOf(receivedPayments);
140	    }
141	
142	    public List<String> refundedPaymentIds() {
143	        return List.copyOf(refundedPaymentIds);
144	    }
145	
146	    // ---- 핸들러 ----
147	
148	    private void handle(HttpExchange ex) throws IOException {
149	        try {
150	            String path = ex.getRequestURI().getPath();
151	            if (!"POST".equals(ex.getRequestMethod())) {
152	                respond(ex, 405, "{}");
153	            } else if (path.equals("/v1/payments")) {
154	                handlePayment(ex);
155	            } else if (path.matches("/v1/payments/[^/]+/refund")) {
156	                handleRefund(ex, path.split("/")[3]);
157	            } else {
158	                respond(ex, 404, "{}");
159	            }
160	        } catch (RuntimeException e) {
161	            respond(ex, 500, "{}");
162	        } finally {
163	            ex.close();
164	        }
165	    }
166	
167	    private void handlePayment(HttpExchange ex) throws IOException {
168	        String key = ex.getRequestHeaders().getFirst("Idempotency-Key");
169	        String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
170	        paymentCalls.incrementAndGet();
171	        receivedPayments.add(new ReceivedPayment(key, body));
172	        switch (paymentMode) {
173	            case SERVER_ERROR -> respond(ex, 500, "{\"error\":\"boom\"}");
174	            case DELAY -> {
175	                sleep(delayMillis);
176	                respond(ex, 200, paymentResult(key, "APPROVED"));
177	            }
178	            case DECLINE -> respond(ex, 200, paymentResult(key, "DECLINED"));
179	            default -> respond(ex, 200, paymentResult(key, "APPROVED"));
180	        }
181	    }
182	
183	    /** 같은 Idempotency-Key면 최초 결과를 그대로 돌려준다. */
184	    private String paymentResult(String key, String status) {
185	        return paymentResultsByKey.computeIfAbsent(key == null ? "" : key, k ->
186	                "{\"paymentId\":\"pay_" + paymentIdSeq.incrementAndGet() + "\",\"status\":\"" + status + "\"}");
187	    }
188	
189	    private void handleRefund(HttpExchange ex, String paymentId) throws IOException {
190	        ex.getRequestBody().readAllBytes();
191	        refundCalls.incrementAndGet();
192	        refundedPaymentIds.add(paymentId);
193	        switch (refundMode) {
194	            case SERVER_ERROR -> respond(ex, 500, "{\"error\":\"boom\"}");
195	            case DELAY -> {
196	                sleep(delayMillis);
197	                respond(ex, 200, refundBody(paymentId));
198	            }
199	            default -> respond(ex, 200, refundBody(paymentId));
200	        }
201	    }
202	
203	    private static String refundBody(String paymentId) {
204	        return "{\"paymentId\":\"" + paymentId + "\",\"status\":\"REFUNDED\"}";
205	    }
206	
207	    private static void sleep(long millis) {
208	        try {
209	            Thread.sleep(millis);
210	        } catch (InterruptedException e) {
211	            Thread.currentThread().interrupt();
212	        }
213	    }
214	
215	    private static void respond(HttpExchange ex, int status, String body) throws IOException {
216	        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
217	        ex.getResponseHeaders().set("Content-Type", "application/json");
218	        try {
219	            ex.sendResponseHeaders(status, bytes.length);
220	            try (OutputStream os = ex.getResponseBody()) {
221	                os.write(bytes);
222	            }
223	        } catch (IOException ignored) {
224	            // 클라이언트가 타임아웃으로 먼저 끊은 경우
225	        }
226	    }
227	}
