package com.example.order.orders;

import com.example.order.common.error.BusinessException;
import com.example.order.common.error.ErrorCode;
import com.example.order.idempotency.StoredResponse;
import com.example.order.orders.dto.CreateOrderRequest;
import com.example.order.orders.dto.OrderPageResponse;
import com.example.order.orders.dto.OrderResponse;
import com.example.order.orders.dto.PayRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

// 주의: 클래스에 @Validated를 붙이지 않는다 (MVC 내장 메서드 검증 -> HandlerMethodValidationException)
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderFacade orderFacade;
    private final OrderService orderService;

    public OrderController(OrderFacade orderFacade, OrderService orderService) {
        this.orderFacade = orderFacade;
        this.orderService = orderService;
    }

    @PostMapping
    public ResponseEntity<String> create(
            @RequestHeader("X-User-Id") @NotBlank @Size(max = 50) String userId,
            @RequestHeader("Idempotency-Key") @NotBlank @Size(max = 64) String idempotencyKey,
            @Valid @RequestBody CreateOrderRequest request) {
        return toResponse(orderFacade.create(userId, idempotencyKey, request));
    }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable long id) {
        return orderService.get(id);
    }

    @GetMapping
    public OrderPageResponse list(
            @RequestParam(required = false) @Size(max = 50) String userId,
            @RequestParam(required = false) String status,
            @RequestParam(defaultValue = "20") @Min(1) @Max(100) int size,
            @RequestParam(required = false) String cursor) {
        OrderStatus statusFilter = null;
        if (status != null && !status.isEmpty()) {
            try {
                statusFilter = OrderStatus.valueOf(status);
            } catch (IllegalArgumentException e) {
                throw new BusinessException(ErrorCode.VALIDATION_ERROR, "정의되지 않은 status 입니다: " + status);
            }
        }
        String userFilter = (userId == null || userId.isEmpty()) ? null : userId;
        String cursorValue = (cursor == null || cursor.isEmpty()) ? null : cursor;
        return orderService.list(userFilter, statusFilter, size, cursorValue);
    }

    @PostMapping("/{id}/pay")
    public ResponseEntity<String> pay(
            @PathVariable long id,
            @RequestHeader("Idempotency-Key") @NotBlank @Size(max = 64) String idempotencyKey,
            @RequestHeader(value = "X-User-Id", required = false) String userId,
            @Valid @RequestBody PayRequest request) {
        return toResponse(orderFacade.pay(id, userId, idempotencyKey, request));
    }

    @PostMapping("/{id}/cancel")
    public OrderResponse cancel(@PathVariable long id) {
        return orderService.cancel(id);
    }

    @PostMapping("/{id}/ship")
    public OrderResponse ship(@PathVariable long id) {
        return orderService.ship(id);
    }

    @PostMapping("/{id}/deliver")
    public OrderResponse deliver(@PathVariable long id) {
        return orderService.deliver(id);
    }

    private static ResponseEntity<String> toResponse(StoredResponse stored) {
        ResponseEntity.BodyBuilder builder = ResponseEntity.status(stored.status())
                .contentType(MediaType.APPLICATION_JSON);
        if (stored.location() != null) {
            builder.header(HttpHeaders.LOCATION, stored.location());
        }
        return builder.body(stored.bodyJson());
    }
}
package com.example.order.common.error;

import java.net.URI;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
    private static final String TYPE_PREFIX = "https://example.com/problems/";

    @ExceptionHandler(BusinessException.class)
    public ResponseEntity<Object> handleBusiness(BusinessException ex) {
        return build(ex.getErrorCode(), ex.getMessage());
    }

    @ExceptionHandler(jakarta.validation.ConstraintViolationException.class)
    public ResponseEntity<Object> handleConstraintViolation(jakarta.validation.ConstraintViolationException ex) {
        return build(ErrorCode.VALIDATION_ERROR, "Request validation failed");
    }

    @ExceptionHandler(DataIntegrityViolationException.class)
    public ResponseEntity<Object> handleDataIntegrity(DataIntegrityViolationException ex) {
        String constraint = ConstraintNames.of(ex);
        if (ConstraintNames.UQ_COUPONS_CODE.equals(constraint)) {
            return build(ErrorCode.DUPLICATE_COUPON_CODE, "이미 존재하는 쿠폰 코드입니다.");
        }
        if (ConstraintNames.UX_ORDERS_ACTIVE_USER_COUPON.equals(constraint)) {
            return build(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
        }
        log.error("Unmapped data integrity violation", ex);
        return build(ErrorCode.INTERNAL_ERROR, "Internal server error");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleAny(Exception ex) {
        log.error("Unhandled exception", ex);
        return build(ErrorCode.INTERNAL_ERROR, "Internal server error");
    }

    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        ProblemDetail pd = ex.getBody();
        pd.setDetail("Request validation failed");
        List<Map<String, String>> errors = ex.getBindingResult().getFieldErrors().stream()
                .map(fe -> Map.of("field", fe.getField(), "message", String.valueOf(fe.getDefaultMessage())))
                .toList();
        pd.setProperty("errors", errors);
        return handleExceptionInternal(ex, pd, headers, status, request);
    }

    @Override
    protected ResponseEntity<Object> handleExceptionInternal(
            Exception ex, Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
        ResponseEntity<Object> base = super.handleExceptionInternal(ex, body, headers, statusCode, request);
        if (base == null) {
            return null;
        }
        ProblemDetail pd = base.getBody() instanceof ProblemDetail p
                ? p
                : ProblemDetail.forStatusAndDetail(statusCode,
                        statusCode.value() >= 500 ? "Internal server error" : String.valueOf(ex.getMessage()));
        ErrorCode code = ErrorCode.fromStatus(statusCode.value());
        pd.setType(URI.create(TYPE_PREFIX + code.typeSlug()));
        pd.setTitle(reason(statusCode.value()));
        pd.setProperty("code", code.name());
        HttpHeaders h = new HttpHeaders();
        h.putAll(base.getHeaders());
        h.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
        return new ResponseEntity<>(pd, h, statusCode);
    }

    private static ResponseEntity<Object> build(ErrorCode code, String detail) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.valueOf(code.status()), detail);
        pd.setType(URI.create(TYPE_PREFIX + code.typeSlug()));
        pd.setTitle(reason(code.status()));
        pd.setProperty("code", code.name());
        return ResponseEntity.status(code.status())
                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
                .body(pd);
    }

    private static String reason(int status) {
        HttpStatus hs = HttpStatus.resolve(status);
        return hs != null ? hs.getReasonPhrase() : "Error";
    }
}
package com.example.order.orders;

import com.example.order.common.error.BusinessException;
import com.example.order.common.error.ErrorCode;
import com.example.order.idempotency.IdempotencyScope;
import com.example.order.idempotency.IdempotencyStore;
import com.example.order.idempotency.RequestHasher;
import com.example.order.idempotency.StoredResponse;
import com.example.order.orders.dto.CreateOrderRequest;
import com.example.order.orders.dto.PayRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/** 멱등 오케스트레이션. 트랜잭션이 없는 빈이다 (begin/release는 각각 별도 단기 트랜잭션). */
@Component
public class OrderFacade {

    private static final Logger log = LoggerFactory.getLogger(OrderFacade.class);

    private final IdempotencyStore idempotencyStore;
    private final RequestHasher hasher;
    private final OrderService orderService;
    private final PaymentService paymentService;

    public OrderFacade(IdempotencyStore idempotencyStore, RequestHasher hasher, OrderService orderService,
                       PaymentService paymentService) {
        this.idempotencyStore = idempotencyStore;
        this.hasher = hasher;
        this.orderService = orderService;
        this.paymentService = paymentService;
    }

    public StoredResponse create(String userId, String idempotencyKey, CreateOrderRequest request) {
        String hash = hasher.hash(IdempotencyScope.ORDER_CREATE, userId, "/api/orders", request);
        IdempotencyStore.BeginResult begin = idempotencyStore.begin(IdempotencyScope.ORDER_CREATE, idempotencyKey, hash);
        if (begin instanceof IdempotencyStore.Replay replay) {
            return replay.response();
        }
        long recordId = ((IdempotencyStore.Acquired) begin).recordId();
        try {
            return orderService.create(userId, request, recordId);
        } catch (RuntimeException e) {
            releaseQuietly(recordId);
            throw e;
        }
    }

    public StoredResponse pay(long orderId, String userId, String idempotencyKey, PayRequest request) {
        String path = "/api/orders/" + orderId + "/pay";
        String hash = hasher.hash(IdempotencyScope.ORDER_PAY, userId, path, request);
        IdempotencyStore.BeginResult begin = idempotencyStore.begin(IdempotencyScope.ORDER_PAY, idempotencyKey, hash);
        if (begin instanceof IdempotencyStore.Replay replay) {
            return replay.response();
        }
        long recordId = ((IdempotencyStore.Acquired) begin).recordId();
        PaymentService.PayOutcome outcome;
        try {
            outcome = paymentService.pay(orderId, request.cardToken(), idempotencyKey, recordId);
        } catch (RuntimeException e) {
            releaseQuietly(recordId);
            throw e;
        }
        if (outcome instanceof PaymentService.Approved approved) {
            return approved.response();
        }
        // Declined: 서비스 트랜잭션(PAYMENT_FAILED)은 이미 커밋됨. 오류이므로 키를 해제하고 402.
        releaseQuietly(recordId);
        throw new BusinessException(ErrorCode.PAYMENT_DECLINED, "결제가 거절되었습니다.");
    }

    private void releaseQuietly(long recordId) {
        try {
            idempotencyStore.release(recordId);
        } catch (RuntimeException ex) {
            log.error("멱등 레코드 해제 실패: id={}", recordId, ex);
        }
    }
}

package com.example.order.orders;

import com.example.order.common.error.BusinessException;
import com.example.order.common.error.ConstraintNames;
import com.example.order.common.error.ErrorCode;
import com.example.order.common.time.Times;
import com.example.order.coupon.Coupon;
import com.example.order.coupon.CouponRepository;
import com.example.order.coupon.DiscountCalculator;
import com.example.order.idempotency.IdempotencyStore;
import com.example.order.idempotency.StoredResponse;
import com.example.order.orders.dto.CreateOrderRequest;
import com.example.order.orders.dto.OrderItemRequest;
import com.example.order.orders.dto.OrderPageResponse;
import com.example.order.orders.dto.OrderResponse;
import com.example.order.payment.PaymentGatewayClient;
import com.example.order.product.Product;
import com.example.order.product.ProductRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Clock;
import java.time.Instant;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    private final OrderRepository orderRepository;
    private final ProductRepository productRepository;
    private final CouponRepository couponRepository;
    private final OrderInventory inventory;
    private final IdempotencyStore idempotencyStore;
    private final PaymentGatewayClient pgClient;
    private final OrderProperties properties;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public OrderService(OrderRepository orderRepository, ProductRepository productRepository,
                        CouponRepository couponRepository, OrderInventory inventory,
                        IdempotencyStore idempotencyStore, PaymentGatewayClient pgClient,
                        OrderProperties properties, ObjectMapper objectMapper, Clock clock) {
        this.orderRepository = orderRepository;
        this.productRepository = productRepository;
        this.couponRepository = couponRepository;
        this.inventory = inventory;
        this.idempotencyStore = idempotencyStore;
        this.pgClient = pgClient;
        this.properties = properties;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    // ------------------------------------------------------------------ 생성 (§6)

    @Transactional
    public StoredResponse create(String userId, CreateOrderRequest req, long idemRecordId) {
        Instant now = Times.now(clock);
        List<OrderItemRequest> items = req.items();

        // ① 404 상품 (요청 순서대로 첫 번째 누락)
        Set<Long> ids = new HashSet<>();
        items.forEach(i -> ids.add(i.productId()));
        Map<Long, Product> products = productRepository.findAllById(ids).stream()
                .collect(Collectors.toMap(Product::getId, Function.identity()));
        for (OrderItemRequest item : items) {
            if (!products.containsKey(item.productId())) {
                throw new BusinessException(ErrorCode.PRODUCT_NOT_FOUND,
                        "상품을 찾을 수 없습니다: id=" + item.productId());
            }
        }

        // ② 404 쿠폰
        Coupon coupon = null;
        if (req.couponCode() != null) {
            if (req.couponCode().indexOf('\u0000') >= 0) { // PostgreSQL이 NUL 문자열을 거부하므로 조회 없이 미존재 처리
                throw new BusinessException(ErrorCode.COUPON_NOT_FOUND, "쿠폰을 찾을 수 없습니다.");
            }
            coupon = couponRepository.findByCode(req.couponCode())
                    .orElseThrow(() -> new BusinessException(ErrorCode.COUPON_NOT_FOUND,
                            "쿠폰을 찾을 수 없습니다: code=" + req.couponCode()));
        }

        // ③ 금액 계산
        long subtotal = 0;
        for (OrderItemRequest item : items) {
            subtotal = Math.addExact(subtotal,
                    Math.multiplyExact(products.get(item.productId()).getPrice(), (long) item.quantity()));
        }
        long discount = coupon == null ? 0L : DiscountCalculator.discount(coupon, subtotal);

        // ④ 409 재고: productId 오름차순으로 조건부 UPDATE
        List<OrderItemRequest> byProductId = items.stream()
                .sorted(Comparator.comparing(OrderItemRequest::productId)).toList();
        for (OrderItemRequest item : byProductId) {
            if (productRepository.tryReserve(item.productId(), item.quantity()) == 0) {
                throw new BusinessException(ErrorCode.INSUFFICIENT_STOCK,
                        "재고가 부족합니다: productId=" + item.productId());
            }
        }

        // ⑤ 409 쿠폰
        if (coupon != null) {
            if (now.isBefore(coupon.getValidFrom()) || !now.isBefore(coupon.getValidUntil())) {
                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "쿠폰 유효기간이 아닙니다.");
            }
            if (subtotal < coupon.getMinOrderAmount()) {
                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "최소 주문 금액 미달입니다.");
            }
            couponRepository.lockById(coupon.getId());
            if (orderRepository.existsActiveCouponUsage(userId, coupon.getCode())) {
                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
            }
            if (couponRepository.tryUse(coupon.getId()) == 0) {
                throw new BusinessException(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다.");
            }
        }

        // ⑥ 저장
        Instant expiresAt = Times.truncate(now.plus(properties.paymentTtl()));
        Order order = new Order(userId, coupon == null ? null : coupon.getCode(), subtotal, discount, now, expiresAt);
        int lineNo = 0;
        for (OrderItemRequest item : items) {
            order.addItem(lineNo++, item.productId(), item.quantity(), products.get(item.productId()).getPrice());
        }
        try {
            orderRepository.saveAndFlush(order);
        } catch (DataIntegrityViolationException e) {
            if (ConstraintNames.UX_ORDERS_ACTIVE_USER_COUPON.equals(ConstraintNames.of(e))) {
                throw new BusinessException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
            }
            throw e;
        }

        // ⑦ 응답 직렬화 + 멱등 완료 기록 (같은 트랜잭션)
        String location = "/api/orders/" + order.getId();
        String json = toJson(OrderResponse.from(order));
        idempotencyStore.complete(idemRecordId, 201, json, location);
        return new StoredResponse(201, json, location);
    }

    // ------------------------------------------------------------------ 조회

    @Transactional(readOnly = true)
    public OrderResponse get(long id) {
        return orderRepository.findById(id)
                .map(OrderResponse::from)
                .orElseThrow(() -> notFound(id));
    }

    @Transactional(readOnly = true)
    public OrderPageResponse list(String userId, OrderStatus status, int size, String cursor) {
        if (userId != null && userId.indexOf('\u0000') >= 0) { // NUL이 든 userId는 존재할 수 없으므로 쿼리 없이 빈 페이지
            return new OrderPageResponse(List.of(), null);
        }
        CursorCodec.Cursor c = cursor == null ? null : CursorCodec.decode(cursor);
        List<Order> rows = orderRepository.findPage(userId, status, c, size + 1);
        boolean hasNext = rows.size() > size;
        List<Order> page = hasNext ? rows.subList(0, size) : rows;
        String nextCursor = hasNext ? CursorCodec.encode(page.get(page.size() - 1)) : null;
        return new OrderPageResponse(page.stream().map(OrderResponse::from).toList(), nextCursor);
    }

    // ------------------------------------------------------------------ 취소·환불 (§8)

    @Transactional
    public OrderResponse cancel(long id) {
        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
        Instant now = Times.now(clock);
        switch (order.getStatus()) {
            case PENDING_PAYMENT -> {
                if (!now.isBefore(order.getExpiresAt())) {
                    throw invalidState(order); // 만료 전이는 스위퍼가 담당
                }
                order.cancel();
                inventory.releaseReservation(order);
                inventory.releaseCoupon(order);
            }
            case PAID -> {
                if (order.getPaymentId() != null) {
                    pgClient.refund(order.getPaymentId()); // 장애 시 예외 -> 롤백 -> 503
                }
                order.refund();
                inventory.restock(order);
                inventory.releaseCoupon(order);
            }
            default -> throw invalidState(order);
        }
        orderRepository.flush();
        return OrderResponse.from(order);
    }

    // ------------------------------------------------------------------ 배송 (§8)

    @Transactional
    public OrderResponse ship(long id) {
        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
        if (order.getStatus() != OrderStatus.PAID) {
            throw invalidState(order);
        }
        order.ship();
        return OrderResponse.from(order);
    }

    @Transactional
    public OrderResponse deliver(long id) {
        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> notFound(id));
        if (order.getStatus() != OrderStatus.SHIPPED) {
            throw invalidState(order);
        }
        order.deliver();
        return OrderResponse.from(order);
    }

    // ------------------------------------------------------------------ 만료 (§9)

    /** 스위퍼 전용. 주문 1건당 1 트랜잭션. 이미 처리됐거나 다른 트랜잭션이 잠근 주문은 건너뛴다. */
    @Transactional
    public boolean expire(long id, Instant now) {
        return orderRepository.lockExpiredForSweep(id, now).map(order -> {
            order.expire();
            inventory.releaseReservation(order);
            inventory.releaseCoupon(order);
            log.debug("expired order id={}", id);
            return true;
        }).orElse(false);
    }

    // ------------------------------------------------------------------ 공통

    private String toJson(OrderResponse response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("응답 직렬화 실패", e);
        }
    }

    private static BusinessException notFound(long id) {
        return new BusinessException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + id);
    }

    private static BusinessException invalidState(Order order) {
        return new BusinessException(ErrorCode.INVALID_STATE,
                "처리할 수 없는 주문 상태입니다: id=" + order.getId() + ", status=" + order.getStatus());
    }
}
package com.example.order.orders;

import com.example.order.common.error.BusinessException;
import com.example.order.common.error.ErrorCode;
import com.example.order.common.time.Times;
import com.example.order.idempotency.IdempotencyStore;
import com.example.order.idempotency.StoredResponse;
import com.example.order.orders.dto.OrderResponse;
import com.example.order.payment.PaymentGatewayClient;
import com.example.order.payment.PgPaymentResult;
import com.example.order.payment.PgPaymentStatus;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Clock;
import java.time.Instant;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService {

    /** 결제 결과. 거절은 예외가 아니라 값으로 반환해야 PAYMENT_FAILED 전이가 커밋된다. */
    public sealed interface PayOutcome permits Approved, Declined {
    }

    public record Approved(StoredResponse response) implements PayOutcome {
    }

    public record Declined() implements PayOutcome {
    }

    private final OrderRepository orderRepository;
    private final OrderInventory inventory;
    private final IdempotencyStore idempotencyStore;
    private final PaymentGatewayClient pgClient;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public PaymentService(OrderRepository orderRepository, OrderInventory inventory,
                          IdempotencyStore idempotencyStore, PaymentGatewayClient pgClient,
                          ObjectMapper objectMapper, Clock clock) {
        this.orderRepository = orderRepository;
        this.inventory = inventory;
        this.idempotencyStore = idempotencyStore;
        this.pgClient = pgClient;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    /** 주문 행 잠금(FOR UPDATE)을 PG 호출 동안 유지한다 (§7). */
    @Transactional
    public PayOutcome pay(long orderId, String cardToken, String idempotencyKey, long idemRecordId) {
        // ① 잠금 + 404
        Order order = orderRepository.findByIdForUpdate(orderId)
                .orElseThrow(() -> new BusinessException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + orderId));

        // ② 상태·만료 검사 -> 409
        Instant now = Times.now(clock);
        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || !now.isBefore(order.getExpiresAt())) {
            throw new BusinessException(ErrorCode.INVALID_STATE,
                    "결제할 수 없는 주문 상태입니다: id=" + orderId + ", status=" + order.getStatus());
        }

        // ③ PG 호출 (total=0이면 생략)
        String paymentId = null;
        if (order.getTotalPrice() > 0) {
            PgPaymentResult result = pgClient.pay(orderId, order.getTotalPrice(), cardToken, idempotencyKey);
            paymentId = result.paymentId();
            if (result.status() == PgPaymentStatus.DECLINED) {
                // ④ 거절: PAYMENT_FAILED + 예약·쿠폰 복원, 커밋
                order.markPaymentFailed(paymentId);
                inventory.releaseReservation(order);
                inventory.releaseCoupon(order);
                orderRepository.flush();
                return new Declined();
            }
        }

        // ⑤ 승인 (또는 total=0)
        order.markPaid(paymentId, Times.now(clock));
        inventory.commitReservation(order);
        orderRepository.flush();
        String json = toJson(OrderResponse.from(order));
        idempotencyStore.complete(idemRecordId, 200, json, null);
        return new Approved(new StoredResponse(200, json, null));
    }

    private String toJson(OrderResponse response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("응답 직렬화 실패", e);
        }
    }
}
package com.example.order.orders;

import jakarta.persistence.EntityManager;
import jakarta.persistence.TypedQuery;
import java.util.List;

public class OrderQueryRepositoryImpl implements OrderQueryRepository {

    private final EntityManager em;

    public OrderQueryRepositoryImpl(EntityManager em) {
        this.em = em;
    }

    @Override
    public List<Order> findPage(String userId, OrderStatus status, CursorCodec.Cursor cursor, int limit) {
        StringBuilder jpql = new StringBuilder("select o from Order o where 1=1");
        if (userId != null) {
            jpql.append(" and o.userId = :userId");
        }
        if (status != null) {
            jpql.append(" and o.status = :status");
        }
        if (cursor != null) {
            jpql.append(" and (o.createdAt < :cAt or (o.createdAt = :cAt and o.id < :cId))");
        }
        jpql.append(" order by o.createdAt desc, o.id desc");

        TypedQuery<Order> q = em.createQuery(jpql.toString(), Order.class);
        if (userId != null) {
            q.setParameter("userId", userId);
        }
        if (status != null) {
            q.setParameter("status", status);
        }
        if (cursor != null) {
            q.setParameter("cAt", cursor.createdAt());
            q.setParameter("cId", cursor.id());
        }
        q.setMaxResults(limit);
        return q.getResultList();
    }
}
package com.example.order.orders;

import com.example.order.common.error.BusinessException;
import com.example.order.common.error.ErrorCode;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;

/** base64url(무패딩)( "{epochMicros}:{id}" ) */
public final class CursorCodec {

    // PostgreSQL timestamptz 범위 안전 마진: 0001-01-01 ~ 9999-12-31
    private static final long MIN_MICROS = -62_135_596_800L * 1_000_000L;
    private static final long MAX_MICROS = 253_402_300_799L * 1_000_000L;

    public record Cursor(Instant createdAt, long id) {
    }

    private CursorCodec() {
    }

    public static String encode(Order order) {
        Instant t = order.getCreatedAt();
        long micros = t.getEpochSecond() * 1_000_000L + t.getNano() / 1_000;
        String raw = micros + ":" + order.getId();
        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
    }

    public static Cursor decode(String cursor) {
        try {
            String raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
            String[] parts = raw.split(":", -1);
            if (parts.length != 2) {
                throw invalid();
            }
            long micros = Long.parseLong(parts[0]);
            long id = Long.parseLong(parts[1]);
            if (id <= 0 || micros < MIN_MICROS || micros > MAX_MICROS) {
                throw invalid();
            }
            return new Cursor(
                    Instant.ofEpochSecond(Math.floorDiv(micros, 1_000_000L), Math.floorMod(micros, 1_000_000L) * 1_000L),
                    id);
        } catch (IllegalArgumentException e) { // base64 오류, NumberFormatException 포함
            throw invalid();
        }
    }

    private static BusinessException invalid() {
        return new BusinessException(ErrorCode.VALIDATION_ERROR, "cursor를 해석할 수 없습니다.");
    }
}
