        // 허용 케이스는 DB 공유로 인한 중복을 피하려고 고유 접미사를 붙이지 않고 최초 1회만 성공하도록 이름을 만든다.
        String effective = expectedStatus == 201 && code.length() == 4 ? uniqueCode("") .substring(0, 4) : code;
        if (expectedStatus == 201 && code.length() == 20) {
