            "RATE,10,9999,10000,1,1000",
            // subtotal 상한: FIXED value > subtotal
            "FIXED,50000,-1,10000,1,10000",
            // subtotal 상한: max 도 subtotal 보다 큼
            "FIXED,20000,30000,10000,1,10000",
