    void c4_allEnvironmentVariables_areHonored() throws Exception {
        int port = freePort();
        Map<String, String> env = new java.util.HashMap<>(dbEnv());
        env.put("SERVER_PORT", String.valueOf(port));
        env.put("PAYMENT_GATEWAY_URL", PG.baseUrl());
