package com.example.order.orders;

import com.example.order.coupon.CouponRepository;
import com.example.order.product.ProductRepository;
import java.util.Comparator;
import java.util.List;
import org.springframework.stereotype.Component;

/**
 * 주문 상태 전이에 따른 재고·쿠폰 카운터 변경(전부 네이티브 UPDATE). 호출자의 트랜잭션 안에서 실행된다.
 * 상품은 항상 productId 오름차순으로 갱신해 잠금 순서를 고정한다.
 */
@Component
class OrderInventory {

    private final ProductRepository productRepository;
    private final CouponRepository couponRepository;

    OrderInventory(ProductRepository productRepository, CouponRepository couponRepository) {
        this.productRepository = productRepository;
        this.couponRepository = couponRepository;
    }

    /** 거절·만료·취소: reserved -= q */
    void releaseReservation(Order order) {
        for (OrderItem i : sorted(order)) {
            productRepository.releaseReservation(i.getProductId(), i.getQuantity());
        }
    }

    /** 결제 승인: stock -= q, reserved -= q */
    void commitReservation(Order order) {
        for (OrderItem i : sorted(order)) {
            productRepository.commitReservation(i.getProductId(), i.getQuantity());
        }
    }

    /** 환불: stock += q */
    void restock(Order order) {
        for (OrderItem i : sorted(order)) {
            productRepository.restock(i.getProductId(), i.getQuantity());
        }
    }

    /** 쿠폰 사용 복원 (쿠폰이 있을 때만) */
    void releaseCoupon(Order order) {
        if (order.getCouponCode() != null) {
            couponRepository.releaseUse(order.getCouponCode());
        }
    }

    private static List<OrderItem> sorted(Order order) {
        return order.getItems().stream().sorted(Comparator.comparing(OrderItem::getProductId)).toList();
    }
}
package com.example.order.orders;

import jakarta.persistence.LockModeType;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface OrderRepository extends JpaRepository<Order, Long>, OrderQueryRepository {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select o from Order o where o.id = :id")
    Optional<Order> findByIdForUpdate(@Param("id") Long id);

    @Query(value = """
            SELECT EXISTS (SELECT 1 FROM orders
                            WHERE user_id = :userId AND coupon_code = :code
                              AND status IN ('PENDING_PAYMENT','PAID','SHIPPED','DELIVERED'))""",
            nativeQuery = true)
    boolean existsActiveCouponUsage(@Param("userId") String userId, @Param("code") String code);

    @Query(value = """
            SELECT id FROM orders
             WHERE status = 'PENDING_PAYMENT' AND expires_at <= :now
             ORDER BY expires_at LIMIT :limit""", nativeQuery = true)
    List<Long> findExpiredIds(@Param("now") Instant now, @Param("limit") int limit);

    @Query(value = """
            SELECT * FROM orders
             WHERE id = :id AND status = 'PENDING_PAYMENT' AND expires_at <= :now
             FOR UPDATE SKIP LOCKED""", nativeQuery = true)
    Optional<Order> lockExpiredForSweep(@Param("id") long id, @Param("now") Instant now);
}
package com.example.order.coupon;

public final class DiscountCalculator {

    private DiscountCalculator() {
    }

    /** R2.4: FIXED=value, RATE=floor(subtotal*value/100) -> maxDiscountAmount 상한 -> subtotal 상한 */
    public static long discount(Coupon coupon, long subtotal) {
        long d = coupon.getType() == CouponType.FIXED
                ? coupon.getValue()
                : Math.multiplyExact(subtotal, coupon.getValue()) / 100;
        if (coupon.getMaxDiscountAmount() != null) {
            d = Math.min(d, coupon.getMaxDiscountAmount());
        }
        return Math.min(d, subtotal);
    }
}
package com.example.order.orders;

import com.example.order.common.time.Times;
import java.time.Clock;
import java.time.Instant;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class OrderExpirySweeper {

    private static final Logger log = LoggerFactory.getLogger(OrderExpirySweeper.class);
    private static final int BATCH_SIZE = 200;

    private final OrderRepository orderRepository;
    private final OrderService orderService;
    private final Clock clock;

    public OrderExpirySweeper(OrderRepository orderRepository, OrderService orderService, Clock clock) {
        this.orderRepository = orderRepository;
        this.orderService = orderService;
        this.clock = clock;
    }

    @Scheduled(fixedDelayString = "${order.expiry-sweep-interval-ms:500}")
    public void sweep() {
        Instant now = Times.now(clock);
        List<Long> ids;
        try {
            ids = orderRepository.findExpiredIds(now, BATCH_SIZE);
        } catch (RuntimeException e) {
            log.warn("만료 대상 조회 실패: {}", e.toString());
            return;
        }
        for (Long id : ids) {
            try {
                orderService.expire(id, now); // 주문 1건당 개별 트랜잭션
            } catch (RuntimeException e) {
                log.warn("주문 만료 처리 실패: id={}", id, e);
            }
        }
    }
}
package com.example.order.common.config;

import com.example.order.payment.PaymentGatewayProperties;
import java.net.http.HttpClient;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.RestClient;

@Configuration
public class PaymentGatewayConfig {

    @Bean
    public RestClient pgRestClient(PaymentGatewayProperties props) {
        HttpClient http = HttpClient.newBuilder()
                .connectTimeout(props.timeout())
                .version(HttpClient.Version.HTTP_1_1) // JDK HttpServer 스텁과의 h2c 업그레이드 이슈 회피
                .build();
        JdkClientHttpRequestFactory rf = new JdkClientHttpRequestFactory(http);
        rf.setReadTimeout(props.timeout());
        return RestClient.builder()
                .baseUrl(stripTrailingSlash(props.url()))
                .requestFactory(rf)
                .build();
    }

    private static String stripTrailingSlash(String url) {
        String u = url;
        while (u.endsWith("/")) {
            u = u.substring(0, u.length() - 1);
        }
        return u;
    }
}
package com.example.order.idempotency;

import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonProcessingException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import org.springframework.stereotype.Component;

@Component
public class RequestHasher {

    private final ObjectMapper canonicalMapper;

    public RequestHasher(ObjectMapper objectMapper) {
        this.canonicalMapper = objectMapper.copy().configure(MapperFeature.SORT_PROPERTIES_ALPHABETICALLY, true);
    }

    /** canonical = scope \n userId(없으면 "") \n "POST " path \n canonicalJson(dto) -> SHA-256 hex */
    public String hash(IdempotencyScope scope, String userId, String path, Object requestDto) {
        String json;
        try {
            json = canonicalMapper.writeValueAsString(requestDto);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("요청 직렬화 실패", e);
        }
        String canonical = scope.name() + "\n"
                + (userId == null ? "" : userId) + "\n"
                + "POST " + path + "\n"
                + json;
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(canonical.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}
package com.example.order.product;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ProductRepository extends JpaRepository<Product, Long> {

    /** 0이면 재고 부족 -> 409 INSUFFICIENT_STOCK */
    @Modifying
    @Query(value = "UPDATE products SET reserved = reserved + :qty WHERE id = :id AND stock - reserved >= :qty",
            nativeQuery = true)
    int tryReserve(@Param("id") long id, @Param("qty") int qty);

    /** 거절·만료·취소 */
    @Modifying
    @Query(value = "UPDATE products SET reserved = reserved - :qty WHERE id = :id", nativeQuery = true)
    int releaseReservation(@Param("id") long id, @Param("qty") int qty);

    /** 결제 승인 */
    @Modifying
    @Query(value = "UPDATE products SET stock = stock - :qty, reserved = reserved - :qty WHERE id = :id",
            nativeQuery = true)
    int commitReservation(@Param("id") long id, @Param("qty") int qty);

    /** 환불 */
    @Modifying
    @Query(value = "UPDATE products SET stock = stock + :qty WHERE id = :id", nativeQuery = true)
    int restock(@Param("id") long id, @Param("qty") int qty);
}
package com.example.order.coupon;

import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface CouponRepository extends JpaRepository<Coupon, Long> {

    Optional<Coupon> findByCode(String code);

    boolean existsByCode(String code);

    /** 쿠폰 행 잠금 */
    @Query(value = "SELECT id FROM coupons WHERE id = :id FOR NO KEY UPDATE", nativeQuery = true)
    Long lockById(@Param("id") long id);

    /** 0이면 소진 -> 409 COUPON_EXHAUSTED */
    @Modifying
    @Query(value = "UPDATE coupons SET used_count = used_count + 1 WHERE id = :id AND used_count < total_quantity",
            nativeQuery = true)
    int tryUse(@Param("id") long id);

    /** 사용 복원 */
    @Modifying
    @Query(value = "UPDATE coupons SET used_count = used_count - 1 WHERE code = :code AND used_count > 0",
            nativeQuery = true)
    int releaseUse(@Param("code") String code);
}

